namespace Causa.Persistence

open Causa.Domain

/// IF41-STORAGE: causa-storage v1.0.0 file sets (CONTRACT.md wins over docs/CAUSA-DATA-CONTRACT-v1.md).
type CommitOid = CommitOid of string
type RepoPath = RepoPath of string

/// v4.1.5 W1: a causa-storage workspace, the directory of the connected repository that holds `investigations/<id>/`
/// (for example `workspaces/demo/r10`). It is derived, never typed: the catalog workspace is the one
/// `catalog/active.json` names (EXT-DATA-013); a working copy is `workspaces/demo/<run>` (CONTRACT section 9.4).
type Workspace = Workspace of string

/// v4.1.5 W1: what a workspace may be used for. A catalog is read-only (EXT-DATA-013); only a working copy is written
/// (CONTRACT section 9.4; EXT-DATA-006). Both are in the repository the user connected to (EXT-DATA-003).
[<RequireQualifiedAccess>]
type WorkspaceRole =
    | Catalog
    | WorkingCopy

/// v4.1.5 W1: a workspace of the connected repository, with its role. The role is derived, never asserted: the
/// representation is private, a catalog address comes only from WorkspaceAddress.catalog and a working copy only from
/// WorkspaceAddress.workingCopy (EXT-DATA-013; EXT-DATA-006).
[<RequireQualifiedAccess>]
module WorkspaceAddress =
    type T =
        private
            { Dir: Workspace
              Kind: WorkspaceRole }
        member a.Workspace = a.Dir
        member a.Role = a.Kind

    let catalog (workspace: Workspace) : T = { Dir = workspace; Kind = WorkspaceRole.Catalog }

    /// The working copy `workspaces/demo/causa-app-<run>` (CONTRACT section 3, runId ^[a-z0-9][a-z0-9-]{0,63}$) for a
    /// run matching ^[a-z0-9][a-z0-9-]{0,53}$. The reserved `causa-app-` namespace keeps every working copy apart from
    /// the catalog workspaces (demonstration-v1, historical-v1, ...), and any workspace in `catalogs` is refused as well.
    let workingCopy (catalogs: Workspace list) (run: string) : T option =
        let workspace = Workspace("workspaces/demo/causa-app-" + run)
        if System.Text.RegularExpressions.Regex.IsMatch(run, "^[a-z0-9][a-z0-9-]{0,53}\\z") && not (List.contains workspace catalogs) then
            Some { Dir = workspace; Kind = WorkspaceRole.WorkingCopy }
        else
            None

/// v4.1.5 W1: an investigation is identified by where it is and its id: the same case can be stored in two
/// workspaces (causa-data holds identical cases in historical-v1 and demonstration-v1).
type InvestigationRef = { Address: WorkspaceAddress.T; Id: InvestigationId }

/// v4.1.5 W1: an address that may be written. Its only constructor refuses a Catalog, so no catalog investigation can
/// reach a save session (EXT-DATA-013; EXT-DATA-006).
[<RequireQualifiedAccess>]
module Writable =
    type T =
        private
        | Writable of WorkspaceAddress.T

    let ofAddress (address: WorkspaceAddress.T) : T option =
        match address.Role with
        | WorkspaceRole.WorkingCopy -> Some(Writable address)
        | WorkspaceRole.Catalog -> None

    let address (Writable address) : WorkspaceAddress.T = address

type FileSet =
    { Manifest: byte[]
      Events: byte[]
      Snapshot: byte[] }

type VerificationFailure =
    | SchemaInvalid of file: string * detail: string
    | DigestMismatch of field: string
    | ContractValueMismatch of field: string * expected: string * actual: string
    | SnapshotDiffersFromReplay of paths: string list
    | MissingRequiredField of file: string * field: string
    | ReplayRejected of ReplayError
    /// v4.1.5 E1: a CONTRACT section 11.1 reader stage refused the file set; code is the stage's primary code, so
    /// conforming readers agree on it.
    | ReaderStage of code: string * file: string * line: int option * detail: string

type VerifiedInvestigation =
    { Investigation: Investigation
      History: EventEnvelope list
      ReadAt: CommitOid
      /// v4.1.5 W1: the workspace the history was read from.
      Address: WorkspaceAddress.T
      Bytes: FileSet }

type StorageCodec =
    { /// v4.1.5 W1: `<workspace>/investigations/<id>`.
      PathOf: Workspace -> InvestigationId -> RepoPath
      Encode: VerifiedInvestigation -> EventEnvelope list -> FileSet
      /// v4.1.5 C1: the first file set of a new investigation from its command-created history (EXT-DATA-008). It is
      /// Ok only when Verify accepts the result, so a file set that would not verify is never sent.
      EncodeNew: InvestigationId -> EventEnvelope list -> Result<FileSet, VerificationFailure list>
      Verify: WorkspaceAddress.T -> CommitOid -> FileSet -> Result<VerifiedInvestigation, VerificationFailure list> }

namespace Causa.Persistence

/// IF41-WIRE: HTTP as data. Persistence builds requests and decodes answers; the App runtime only executes them
/// through Limen and returns the raw result (decoding stays inside persistence: ODR-V4-06, approved in APR-V4-OWNER-1).
type RequestId = RequestId of int64

type HttpMethod =
    | Get
    | Post
    | Put
    | Patch

type HttpRequest =
    { Id: RequestId
      Method: HttpMethod
      Url: string
      Headers: (string * string) list
      Body: string option }

type TransportFailure =
    | FailedBeforeSending
    | LostAfterSending
    | TimedOut

type HttpOutcome =
    | Answered of RequestId * status: int * headers: (string * string) list * body: string
    | NotAnswered of RequestId * TransportFailure

/// The host's only network operation: execute one request exactly once and return its raw outcome; it never retries.
type Execute = HttpRequest -> HttpOutcome

/// The credential is opaque everywhere: its representation is private to this module, it prints as "<credential>",
/// and its only use is the Authorization header persistence adds to each request (PF-015, INV-21).
[<RequireQualifiedAccess>]
module Credential =
    type T =
        private
        | Token of string
        override _.ToString() = "<credential>"

    let create (token: string) : T = Token token

    let authorization (Token token) : string * string = "Authorization", "Bearer " + token

type Repository = { Owner: string; Name: string; Branch: string }

/// What every request needs after Connect: the repository and the credential. The engine keeps it in its model.
type ConnectionContext = { Repository: Repository; Credential: Credential.T }

/// What an operation may use to emit a request. Every operation emits at most one request, which carries NextId; the
/// engine advances NextId after each operation that emitted one, so identities are unique across the tab.
/// MutationInFlightElsewhere says whether another investigation in this tab has a mutation in flight (T-S04, T-S53).
type RequestContext =
    { Connection: ConnectionContext
      NextId: RequestId
      MutationInFlightElsewhere: bool
      /// v4.1.2 (ODR-V412-01): the time of this operation, from the host clock (the engine supplies it; the machines
      /// stay pure). SM-SAVE's reconciliation-read guards count the reads sent in the 60 s before it (INV-04).
      Now: System.DateTimeOffset }

namespace Causa.Persistence

open Causa.Domain

/// IF41-SAVE: the SM-SAVE, SM-CONFLICT and SM-LOAD machines (requirements-compiled/v4/state-machines.json). Pure;
/// effects are data. Each state union has exactly the machine's states and each input union exactly its events
/// (check X05); state-machine-contracts.json decides every (state, input) pair.
/// Confirmation (PERSIST-023): the only proof that a save succeeded. Its representation is private to this module, so
/// no other file, in this assembly or another, can build one; its only constructor requires the bytes re-read at the
/// commit to equal the bytes written. (A caller can still pass the same bytes twice: the plan's INV-01 tests guard
/// that path.)
[<RequireQualifiedAccess>]
module Confirmation =
    type T =
        private
            { Investigation: InvestigationId
              Commit: CommitOid
              CommittedAt: System.DateTimeOffset }
        member c.InvestigationId = c.Investigation
        member c.CommitOid = c.Commit
        member c.CommitTime = c.CommittedAt

    let ofReadBack (investigation: InvestigationId) (commit: CommitOid) (committedAt: System.DateTimeOffset) (written: FileSet) (readBack: FileSet) : T option =
        if written = readBack then Some { Investigation = investigation; Commit = commit; CommittedAt = committedAt } else None

type WriteMarker = { Session: System.Guid; Sequence: int64 }

type SaveFailure =
    | Refused of ProviderError
    | RepositoryKeptChanging
    | BytesDiffer of CommitOid
    | HistoryWasRewritten
    | CredentialNotAccepted

/// An unsaved command the engine refused when it was re-decided against the GitHub version, with the engine's reason
/// (T-C07, PERSIST-012).
type RefusedCommand = { Command: CommandEnvelope; Reason: string }

/// SM-CONFLICT states.
type ConflictView =
    | ReadingRemote of RequestId
    | Reviewable of remote: VerifiedInvestigation
    | Reapplying of remote: VerifiedInvestigation
    | Reapplied of remote: VerifiedInvestigation * refused: RefusedCommand list
    | ConfirmingDiscard of remote: VerifiedInvestigation
    | Discarded of remote: VerifiedInvestigation
    | RemoteUnavailable
    | Unresolvable of reason: string

/// SM-CONFLICT events.
[<RequireQualifiedAccess>]
type ConflictInput =
    | RemoteVerified of VerifiedInvestigation
    | RemoteReadFailed of TransportFailure
    | RemoteMissingOrInvalid of VerificationFailure option
    | ReadAgain
    | ReviewChosen
    | ReapplyChosen
    | ReapplyDone of accepted: CommandEnvelope list * refused: RefusedCommand list
    | DiscardChosen
    | DiscardConfirmed
    | DiscardCancelled
    | ExportChosen
    | SupersededReply of RequestId

/// What a Saved state rests on: a save confirmed by read-back (PERSIST-023), or a verified read at a named commit after
/// a load or a confirmed discard. The owner approved that the second shows as Saved (ODR-V4-08, APR-V4-OWNER-1).
type SavedBasis =
    | Confirmed of Confirmation.T
    | VerifiedAt of VerifiedInvestigation

/// SM-SAVE states (PERSIST-031: exactly seven).
[<RequireQualifiedAccess>]
type SaveState =
    | Saved of SavedBasis
    | Unsaved
    | Saving
    | Offline
    | Conflict of ConflictView
    | UnknownOutcome of automaticReadsLeft: int
    | SaveFailed of SaveFailure

/// SM-SAVE events. Persistence produces every reply event from an HttpOutcome with SaveMachine.Interpret; the App
/// produces only Edit, SaveRequested, CheckAgain, WentOffline, WentOnline, QueuedSaveStarted and MutationSent. Engine.Update
/// (IF41-APP) steps MutationSent with the RequestId in the same update that turns the step's mutation request
/// (Outstanding awaiting MutationAnswer) into HostEffect.Http. The session is unchanged, so a missing MutationSent
/// changes no outcome (T-S61, ODR-V41-08).
[<RequireQualifiedAccess>]
type SaveInput =
    | Edit of CommandEnvelope
    | SaveRequested
    | MutationSent of RequestId
    | ReadBackMatched of Confirmation.T
    | ReadBackMismatched of CommitOid
    | StaleHeadUnrelated of freshHead: CommitOid
    | StaleHeadSameInvestigation of freshHead: CommitOid
    | ProviderRefused of ProviderError
    | CredentialRefused
    | AnswerLost
    | FailedBeforeSending
    | ReconcileMarkerBytesMatch of Confirmation.T
    | ReconcileMarkerBytesDiffer of CommitOid
    | ReconcileNothingWrittenHeadUnchanged
    | ReconcileNothingWrittenHeadMoved of head: CommitOid
    | ReconcileHistoryRewritten
    | ReconcileReadFailed
    | ReconcileReadsSpent
    | CheckAgain
    | WentOffline
    | WentOnline
    | ConflictResolvedReapplied of CommandEnvelope list
    | ConflictResolvedDiscarded of VerifiedInvestigation
    | SupersededReply of RequestId
    | QueuedSaveStarted
    | RebaseReadFailed
    | ReadBackReadFailed

/// Why a load failed: the files did not verify, or the provider refused or did not answer (IF41-ERRORS), so the
/// application can state the cause truthfully (PERSIST-024).
type LoadFailure =
    | Unverifiable of VerificationFailure list
    | ProviderFailed of ProviderError

/// The read a load is waiting for.
type LoadAwaiting =
    | LoadHead
    | LoadFilesAt of CommitOid

/// SM-LOAD states.
type LoadState =
    | NotLoaded
    | Loading of RequestId * LoadAwaiting
    | Loaded of VerifiedInvestigation
    | LoadFailed of LoadFailure
    | UnavailableOffline

/// SM-LOAD events.
[<RequireQualifiedAccess>]
type LoadInput =
    | OpenRequested of InvestigationRef
    | LoadVerified of VerifiedInvestigation
    | LoadRejected of LoadFailure
    | WentOffline
    | WentOnline
    | RefreshRequested
    | SupersededReply of RequestId

type Politeness =
    | Polite
    | Assertive

type SaveEffect =
    | Send of HttpRequest
    | ScheduleReconcileRead of InvestigationRef * afterMilliseconds: int
    | Announce of Politeness * text: string
    | ExportCommands of CommandEnvelope list

/// The fail-closed answer to an illegal (state, input) pair: state, base head and unsaved changes are unchanged.
type SaveFault = { Machine: string; State: string; Input: string; Reason: string }

/// The answer a session is waiting for, so Interpret knows what it means. These are steps inside Saving and
/// UnknownOutcome; no machine state is added.
type Awaiting =
    | MutationAnswer
    | ReadBackAt of CommitOid
    | FreshHead
    | FileComparisonAt of freshHead: CommitOid
    | ReconcileHead
    | ReconcileCommits of page: int
    | ReconcileFilesAt of CommitOid

type InvestigationSession =
    { Id: InvestigationId
      /// v4.1.5 W1: where the investigation is saved. Only a working copy has a session (T-L03 as amended by ODR-V415-01).
      Address: Writable.T
      BaseHead: CommitOid
      State: SaveState
      Unsaved: CommandEnvelope list
      AfterInFlight: CommandEnvelope list
      Outstanding: (RequestId * Awaiting) option
      Mutations: int
      RebaseAttempts: int
      ReconcileReads: int
      /// v4.1.2 (ODR-V412-01): when each reconciliation read of this session was sent, automatic or not, newest first.
      /// One entry per reconciliation read: the first request of a reconciliation; the commit pages and file reads that
      /// complete the same reconciliation are not further reads. Every operation that sends a reconciliation read
      /// (ReconcileDue, T-S31, T-S32) sends it only while fewer than four entries fall in the 60 s before
      /// RequestContext.Now (INV-04), and records it here. Never cleared; older entries count for nothing.
      ReconcileReadsSentAt: System.DateTimeOffset list }

/// What one answer means for a session.
type Interpretation =
    /// The answer completes a step: apply this event with SaveMachine.Step.
    | MachineEvent of SaveInput
    /// The answer leads to the next read of the same step (read-back after the mutation, file comparison after a
    /// fresh head, the next reconciliation page): send the request; the session, whose Outstanding now names it, keeps
    /// its state.
    | NextRequest of InvestigationSession * HttpRequest

/// What one answer means for a load.
type LoadInterpretation =
    | LoadEvent of LoadInput
    | LoadNextRequest of LoadState * HttpRequest

/// What one answer means for a conflict review.
type ConflictInterpretation =
    | ConflictEvent of ConflictInput
    | ConflictNextRequest of ConflictView * HttpRequest

/// v4.1.5 L1: one investigation a workspace holds. For a catalog, the title and expected state digest come from the
/// catalog manifest (EXT-DATA-013); for a working copy they are absent until the investigation is opened.
type ListedInvestigation = { Ref: InvestigationRef; Path: RepoPath; Title: string option; ExpectedStateSha256: string option }

/// v4.1.5 L1, W1: what to list. ActiveCatalog derives the catalog workspace from `catalog/active.json`; a working copy
/// comes only from WorkspaceAddress.workingCopy.
type ListingTarget =
    | ActiveCatalog
    | WorkingCopyOf of WorkspaceAddress.T

/// v4.1.5 L1: the read a listing is waiting for, so InterpretList knows what an answer means and at which commit.
type ListingStep =
    | ListHead
    | ListActiveCatalogAt of CommitOid
    | ListManifestAt of CommitOid * Workspace
    | ListDirectoryAt of CommitOid * Workspace

/// v4.1.5 L1: a workspace's investigations, all read at one commit.
type Listing = { Address: WorkspaceAddress.T; ReadAt: CommitOid; Investigations: ListedInvestigation list }

/// v4.1.5 L1: what one answer means for a listing. A listing is a read, like a load's head-then-files steps; it adds
/// no machine state.
type ListingInterpretation =
    | ListingComplete of Listing
    | ListingNextRequest of ListingStep * HttpRequest
    | ListingFailed of LoadFailure

/// v4.1.5 L1, W1: listing a workspace. Nothing is written (EXT-DATA-006). A working copy that does not exist yet lists
/// as empty at the head read (EXT-DATA-009: a clean start).
type WorkspaceLister =
    { List: RequestContext -> ListingTarget -> ListingStep * HttpRequest
      InterpretList: RequestContext -> ListingTarget -> ListingStep -> HttpOutcome -> ListingInterpretation }

/// Every operation that emits a request uses RequestContext.NextId for it (at most one per call) and records it as
/// Outstanding; an answer whose RequestId is not Outstanding is SupersededReply.
type SaveMachine =
    { Initial: Writable.T -> VerifiedInvestigation -> InvestigationSession
      /// v4.1.5 C1 (address, id, base head, start command, online): a new investigation's session in a working copy at the head just read, holding its
      /// StartInvestigation command (EXT-DATA-008), the only way it starts. It starts in Unsaved when online and in
      /// Offline when known offline (the states T-S01 and T-S02 would reach). Its first save is the existing T-S04: one
      /// commit adding StorageCodec.EncodeNew's three files, conditional on BaseHead, Saved only from an equal read-back
      /// (PERSIST-005..007). On a moved head, files absent at the fresh head are StaleHeadUnrelated and files present
      /// there are StaleHeadSameInvestigation. No state, input or transition is added.
      InitialNew: Writable.T -> InvestigationId -> CommitOid -> CommandEnvelope -> bool -> InvestigationSession
      /// Classifies and verifies one answer (IF41-ERRORS, read-back, reconciliation) against what the session awaits.
      Interpret: RequestContext -> InvestigationSession -> HttpOutcome -> Interpretation
      Step: RequestContext -> InvestigationSession -> SaveInput -> Result<InvestigationSession * SaveEffect list, SaveFault>
      /// The timer of ScheduleReconcileRead fired: in UnknownOutcome with automatic reads left, send the next
      /// reconciliation read (state unchanged); with none left, Step ReconcileReadsSpent. v4.1.2 (ODR-V412-01): the
      /// read is sent, and recorded in ReconcileReadsSentAt, only while fewer than four reconciliation reads were sent
      /// in the 60 s before RequestContext.Now; otherwise ScheduleReconcileRead fires again 60 s after the oldest of
      /// those four, and nothing is sent.
      ReconcileDue: RequestContext -> InvestigationSession -> Result<InvestigationSession * SaveEffect list, SaveFault>
      InterpretConflict: RequestContext -> ConflictView -> HttpOutcome -> ConflictInterpretation
      StepConflict: RequestContext -> ConflictView -> ConflictInput -> Result<ConflictView * SaveEffect list, SaveFault>
      InterpretLoad: RequestContext -> LoadState -> HttpOutcome -> LoadInterpretation
      StepLoad: RequestContext -> LoadState -> LoadInput -> Result<LoadState * SaveEffect list, SaveFault> }

namespace Causa.App

open Causa.Domain
open Causa.Persistence

/// IF41-VIEW: projections the views render (ui and ui-2). Views read only these; they never decide legality.
type SaveAction =
    | Save
    | Retry
    | Reconnect
    | CheckAgainAction
    | Review
    | ReapplyMine
    | DiscardMine
    | ExportMine

type SaveIndicatorView =
    { InvestigationId: InvestigationId
      Label: string
      Text: string
      Glyph: string
      Actions: SaveAction list
      Politeness: Politeness
      LastSavedCommitTime: System.DateTimeOffset option }

type WorkspaceHeaderView =
    { Connection: ConnectionState
      Offline: bool
      NotSaved: (InvestigationId * string) list }

type ScreenView =
    { Route: Route
      Title: string
      Header: WorkspaceHeaderView
      Indicator: SaveIndicatorView option }

type Projections =
    { SaveIndicator: InvestigationSession -> SaveIndicatorView
      Header: Model -> WorkspaceHeaderView
      Screen: Model -> ScreenView }

// ---- IF-UI (CF-09 A, APR-CFUI-OWNER-1): the presentation contract types for screens, folded into IF41-VIEW so no new
// contract file is added (V41Package.fs:1790). Types and signatures only, plus the boundary members that must sit beside
// a private representation (FixtureLabel, Visible, Understood, SafeUrl). The functions over these types are the
// producer's (proposals/r10-contract-first-ui/contracts/Presentation.fs). Identities are InvestigationRef; a route
// carries an unresolved RouteTarget (v4.1.5 W1, rev 3).

// -- Ids.fs --
namespace Causa.Ui.Contracts

/// Stable identifiers. Catalog entries keep their CAT-CAUSA-INVESTIGATION id (INV-0xx) as their field, action or region id,
/// so a UI element, its manifest entry and its Dokimos/catalog check share one name. Entries no catalog item names (the
/// connection form, journey-named actions) get a UIF-/UIA-/UIR- id and cite the source that requires them
/// (SCREEN-MANIFEST.json). The id is also the Limen binding name (data-text, data-event) of the element.
type ScreenId = ScreenId of string
type FieldId = FieldId of string
type ActionId = ActionId of string
type RegionId = RegionId of string

// -- Types.fs --

open System
open System.Text.RegularExpressions
open Causa.Domain
open Causa.Persistence

/// A fixture's label. Every fixture value carries one, so a fixture-backed screen can never be reported as an
/// integrated one (VERIFICATION-STRATEGY.md, Layer A/B versus Layer C). Construct only through FixtureLabel.create.
type FixtureLabel = private FixtureLabel of string

[<RequireQualifiedAccess>]
module FixtureLabel =
    let create (name: string) : FixtureLabel = FixtureLabel("FIXTURE: " + name)
    let value (FixtureLabel s) = s

/// Where a stored record was read: the repository commit when the provider supplied one.
type StoredRef = { Path: string; Commit: string option }

// ---- The three capability boundaries (README.md section 3) ----------------------------------------------------------

/// What the UI is entitled to claim about a value.
type Capability =
    /// Repository status, investigation summaries, metadata and stored records exactly as read. No replay is claimed.
    | DataVisible
    /// Validated projections the domain engine supplied (hypotheses, evidence, relationships, timeline, conclusions,
    /// state). The UI never replays events itself.
    | DataUnderstood
    /// Inputs, commands, validation results and save progress. Persistence and the domain engine decide correctness.
    | DataEditable

/// A value shown as stored (Data Visible). There is no Visible -> Understood conversion. Understood.projected is public,
/// though, so "stored data is never presented as the kernel's interpretation" rests on an ownership rule (only the
/// integration adapter calls Understood.projected; screens and Presentation.fs never do), checked in review, not on
/// the types.
type Visible<'a> =
    private
    | StoredValue of 'a * StoredRef
    | VisibleFixture of 'a * FixtureLabel

/// A value the domain engine projected at a version (Data Understood).
type Understood<'a> =
    private
    | Projected of 'a * AggregateVersion
    | UnderstoodFixture of 'a * FixtureLabel

[<RequireQualifiedAccess>]
module Visible =
    let stored (at: StoredRef) (value: 'a) = StoredValue(value, at)
    let fixture (label: FixtureLabel) (value: 'a) = VisibleFixture(value, label)
    let value v = match v with StoredValue(x, _) | VisibleFixture(x, _) -> x
    let fixtureLabel v = match v with VisibleFixture(_, l) -> Some l | StoredValue _ -> None
    let map f v = match v with StoredValue(x, s) -> StoredValue(f x, s) | VisibleFixture(x, l) -> VisibleFixture(f x, l)

[<RequireQualifiedAccess>]
module Understood =
    /// Only the integration adapter (Ui/UiAdapter.fs), holding a domain projection, may call this. That is an ownership
    /// and review rule: the type does not stop another caller.
    let projected (version: AggregateVersion) (value: 'a) = Projected(value, version)
    let fixture (label: FixtureLabel) (value: 'a) = UnderstoodFixture(value, label)
    let value u = match u with Projected(x, _) | UnderstoodFixture(x, _) -> x
    let version u = match u with Projected(_, v) -> Some v | UnderstoodFixture _ -> None
    let fixtureLabel u = match u with UnderstoodFixture(_, l) -> Some l | Projected _ -> None
    let map f u = match u with Projected(x, v) -> Projected(f x, v) | UnderstoodFixture(x, l) -> UnderstoodFixture(f x, l)

/// A displayed fact, either as stored or as projected; the boundary stays visible to the view.
type Shown<'a> =
    | AsStored of Visible<'a>
    | AsProjected of Understood<'a>

/// A count that may be unknown. Unknown is never rendered as zero (UI-022, UI-001 "where supported").
type Count =
    | Known of int
    | UnknownCount
    | NotSupported

/// Whether an action is offered. The domain engine decides (UI-004); the UI renders only what it is given.
type Availability =
    | Available
    /// Shown disabled with the engine's reason, only when the engine supplies one.
    | Unavailable of reason: string
    /// Not rendered at all.
    | NotOffered

// ---- Validation (catalog validation blocks) ----------------------------------------------------------------------
// Close to Limen.Forms' FieldSpec, but NOT identical: Limen.Forms has Required: bool and no Pattern, counts runes, does
// not trim and reports one error per field; this checks UTF-16 length, trims for MinLength and lists every failed rule.
// Which semantics the product uses is CF-12.

type Rule =
    | Required
    | MinLength of int
    | MaxLength of int
    | Pattern of string
    | OneOf of string list

type ComponentKind =
    | TextInput
    | TextArea
    | UrlInput
    | PasswordInput
    | RadioGroup
    | Select
    | Display
    | Button
    | Link
    | Region

type FieldSpec =
    { Field: FieldId
      /// The accessible name the governed journeys look the field up by (catalog `name`).
      Label: string
      Component: ComponentKind
      Rules: Rule list }

type ValidationError = { Field: FieldId; Rule: Rule; Message: string }

/// An absolute http(s) URL, the only form INV-029 allows to be rendered as a link (UI-005 sanitising).
type SafeUrl = private SafeUrl of string

[<RequireQualifiedAccess>]
module SafeUrl =
    let pattern = @"^https?://[^\s]+$"
    let tryCreate (s: string) =
        let schemeOk = s.StartsWith("http://", StringComparison.Ordinal) || s.StartsWith("https://", StringComparison.Ordinal)
        if schemeOk && Uri.IsWellFormedUriString(s, UriKind.Absolute) && Regex.IsMatch(s, pattern) && s.Length <= 2000 then Some(SafeUrl s)
        else None
    let value (SafeUrl s) = s

/// What a route asks for, exactly as the URL states it. It is not an address: v4.1.5 addresses are derived, never
/// asserted (WorkspaceAddress.catalog / workingCopy, 02-IF41-STORAGE.fs), so whoever holds the listings resolves a target
/// against the workspaces it actually listed, and an unresolved target is not found.
type RouteTarget = { Workspace: string; Role: WorkspaceRole; Id: InvestigationId }

// ---- Failure and loading ---------------------------------------------------------------------------------------------

/// Why data is not shown. Each case has its own plain-language copy (PresentationLanguage.failure, UI-010, UI-028).
/// Qualified access: CredentialRefused would otherwise collide with IF41-APP ConnectionState.CredentialRefused.
[<RequireQualifiedAccess>]
type UiFailure =
    /// Keyed by workspace and id (v4.1.5 W1): the same case can be stored in two workspaces.
    | InvestigationNotFound of RouteTarget
    /// The stored files did not verify (schema, digest, replay refusal). Fails closed: nothing partial is shown.
    | InvalidData of detail: string
    | NotAuthorized
    | CredentialRefused
    | ProviderUnreachable
    | ProviderRateLimited
    /// The provider answered something no case classifies.
    | ProviderError of detail: string
    /// The capability the screen needs is not provided by the current backend or by the frozen contracts.
    | CapabilityAbsent of needed: Capability * because: string

/// Data a screen is waiting for.
type Remote<'a> =
    | NotRequested
    /// The copy describes the user's task (UI-024 "Opening investigation"), never a fabricated progress figure.
    | Waiting of activity: string
    | Ready of 'a
    | Failed of UiFailure

